package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceUtils;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
/** Source/model genesis remains fictional. Admission routes use actual whole native providers and the sole native writer row. */
class ReportInputWriterAdmissionTest {
 boolean mysql(){return false;}
 DailyReportInputComponentTest daily()throws Exception{return new ReportInputCaptureTest(){@Override boolean mysql(){return ReportInputWriterAdmissionTest.this.mysql();}}.daily();}
 ReportPeriodProofNativeTest period(){return new ReportInputCaptureTest(){@Override boolean mysql(){return ReportInputWriterAdmissionTest.this.mysql();}}.period();}
 <T>T rr(PlatformTransactionManager tx,java.util.function.Supplier<T> work){return new ReportInputCaptureTest().rr(tx,work);}
 Prepare command(ReportInputWriterAdmissionService.Captured c){var s=c.scope();return new Prepare(s.logicalKey(),s.generation(),s.stage(),s.day(),null,c.dependencies(),List.of(),c.dependencies().stream().map(Dependency::id).toList(),false,"a".repeat(64));}
 record Period(ReportPeriodProofNativeTest nativeData,ReportInputCaptureService inputs,ReportInputWriterAdmissionService admission,ReportInputWriterAdmissionService.Captured captured){}
 Period admitted(){var f=period();var base=f.f.h.h.f;var inputs=new ReportInputCaptureService(mock(DailyReportInputComponentService.class),f.service,base.tx);var admission=new ReportInputWriterAdmissionService(base.source,base.tx,inputs);var s=new ReportInputCaptureService.Scope("report:weekly:"+ReportPeriodInputComponentTest.LAST,1,Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST);return new Period(f,inputs,admission,admission.capture(s,ReportPeriodInputComponentTest.CUTOFF));}
 @Test void ActualDailyAuthorityRechecksCommittedFactsAndRestoresWritableRcConnection()throws Exception{var f=daily();var base=f.data.nativeData().fixture().f();var inputs=new ReportInputCaptureService(f.service,mock(ReportPeriodInputComponentService.class),base.tx);var admission=new ReportInputWriterAdmissionService(base.source,base.tx,inputs);var day=f.data.nativeData().fixture().day();var c=admission.capture(new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day),f.data.nativeData().cutoff());var result=base.writes.execute(base.action("fictional-report-daily-admit"),k->null,a->{var connection=DataSourceUtils.getConnection(base.source);var proof=admission.asWriterSource(c).snapshot(command(c),c.cutoff());assertSame(connection,DataSourceUtils.getConnection(base.source));assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());assertEquals(TransactionDefinition.ISOLATION_READ_COMMITTED,TransactionSynchronizationManager.getCurrentTransactionIsolationLevel());return proof;});assertEquals(1,result.candidates().size());assertTrue(result.complete());assertEquals(2,base.sends);}
 @Test void ActualPeriodAuthorityAndPureFreezeUseOriginalBodiesAndSixUnknownDates(){var x=admitted();var base=x.nativeData.f.h.h.f;var frozen=base.writes.execute(base.action("fictional-report-period-admit"),k->null,a->new ReportInputSnapshotService(x.admission.asWriterSource(x.captured)).freeze(command(x.captured),x.captured.cutoff()));assertTrue(frozen.hasContent());assertEquals("partial",frozen.coverageState());assertEquals(1,base.sends);assertTrue(x.captured.toString().contains("redacted"));}
 @Test void OriginalCurrentAndNativeLedgerChangesRejectAndWriterBusinessRollsBack(){var x=admitted();var base=x.nativeData.f.h.h.f;var c=x.captured;long before=base.jdbc.queryForObject("SELECT slot_revision FROM worker_lock",Long.class);base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",x.nativeData.f.h.version.contentId());assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-admit-stale"),k->null,a->{base.jdbc.update("UPDATE worker_lock SET slot_revision=slot_revision+1");return x.admission.asWriterSource(c).snapshot(command(c),c.cutoff());}));assertEquals(before,base.jdbc.queryForObject("SELECT slot_revision FROM worker_lock",Long.class));var fresh=x.admission.capture(c.scope(),c.cutoff());var proof=base.writes.execute(base.action("fictional-report-admit-fresh"),k->null,a->x.admission.asWriterSource(fresh).snapshot(command(fresh),fresh.cutoff()));assertTrue(proof.candidates().getFirst().evidence().blocked());assertEquals(1,base.sends);}
 @Test void AlienIssuerScopeDependenciesAndWrongTransactionCannotMintAdmission(){var x=admitted();var base=x.nativeData.f.h.h.f;var c=x.captured;var source=x.admission.asWriterSource(c);assertThrows(RuntimeException.class,()->source.snapshot(command(c),c.cutoff()));assertThrows(RuntimeException.class,()->new ReportInputWriterAdmissionService(base.source,base.tx,x.inputs).asWriterSource(c));assertThrows(RuntimeException.class,()->rr(base.tx,()->source.snapshot(command(c),c.cutoff())));assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-admit-scope"),k->null,a->source.snapshot(new Prepare(c.scope().logicalKey(),2,c.scope().stage(),c.scope().day(),null,c.dependencies(),List.of(),List.of(),false,"a".repeat(64)),c.cutoff())));assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-admit-deps"),k->null,a->source.snapshot(new Prepare(c.scope().logicalKey(),1,c.scope().stage(),c.scope().day(),null,List.of(),List.of(),List.of(),false,"a".repeat(64)),c.cutoff())));assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-admit-cutoff"),k->null,a->source.snapshot(command(c),c.cutoff().plusSeconds(1))));assertThrows(RuntimeException.class,()->rr(base.tx,()->x.admission.capture(c.scope(),c.cutoff())));var wrong=new TransactionTemplate(base.tx);wrong.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->wrong.execute(s->source.snapshot(command(c),c.cutoff())));}
 @Test void SoleNativeWriterLockIsRetainedAfterFreshReadUntilOriginalCommit()throws Exception{var x=admitted();var base=x.nativeData.f.h.h.f;var verified=new CountDownLatch(1);var contenderPrepared=new CountDownLatch(1);var commit=new CountDownLatch(1);var changed=new AtomicBoolean();try(var workers=Executors.newFixedThreadPool(2)){var owner=workers.submit(()->base.writes.execute(base.action("fictional-report-admission-holder"),k->null,a->{var proof=x.admission.asWriterSource(x.captured).snapshot(command(x.captured),x.captured.cutoff());verified.countDown();try{if(!commit.await(500,TimeUnit.MILLISECONDS))throw new AssertionError("native admission commit barrier timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}assertFalse(changed.get());return proof;}));assertTrue(verified.await(5,TimeUnit.SECONDS));var contender=workers.submit(()->base.writes.executePrepared(base.action("fictional-report-admission-contender"),k->null,()->{contenderPrepared.countDown();return a->{changed.set(true);base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",x.nativeData.f.h.version.contentId());return "changed-after-commit";};}));assertTrue(contenderPrepared.await(1,TimeUnit.SECONDS));assertFalse(changed.get());commit.countDown();assertTrue(owner.get(5,TimeUnit.SECONDS).complete());assertEquals("changed-after-commit",contender.get(5,TimeUnit.SECONDS));assertTrue(changed.get());}assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-admission-after-change"),k->null,a->x.admission.asWriterSource(x.captured).snapshot(command(x.captured),x.captured.cutoff())));}
 @Test void ColdMandatoryPortsAndUnknownNativeCaptureNeverBecomeEmptyEvidence(){var source=mock(javax.sql.DataSource.class);var tx=mock(PlatformTransactionManager.class);var inputs=mock(ReportInputCaptureService.class);var service=new ReportInputWriterAdmissionService(source,tx,inputs);verifyNoInteractions(source,tx,inputs);var day=LocalDate.parse("2026-01-01");assertNull(service.capture(new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day),Instant.parse("2026-01-01T21:00:00Z")));verifyNoInteractions(source,tx);assertThrows(RuntimeException.class,()->service.asWriterSource(null));assertThrows(NullPointerException.class,()->new ReportInputWriterAdmissionService(source,tx,null));}
}
